def transform(grid):
    from collections import Counter
    import math

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if len(marks) < 3:
        return [row[:] for row in grid]

    # The scattered non-background cells trace the enclosing boundary.
    # Order them around their center to recover the polygon, then fill it.
    cr = sum(r for r, c in marks) / len(marks)
    cc = sum(c for r, c in marks) / len(marks)
    boundary = sorted(marks, key=lambda p: math.atan2(p[0] - cr, p[1] - cc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            inside = False
            for i in range(len(boundary)):
                r1, c1 = boundary[i]
                r2, c2 = boundary[(i + 1) % len(boundary)]
                if (r1 > r) != (r2 > r):
                    x_cross = c1 + (r - r1) * (c2 - c1) / (r2 - r1)
                    if c < x_cross:
                        inside = not inside
            if inside and grid[r][c] == bg:
                out[r][c] = 3
    return out
