from math import gcd

def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next(v for row in grid for v in row if v != 9)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    out = [row[:] for row in grid]

    # Connect pairs of markers with straight lattice segments.
    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            steps = gcd(abs(r2 - r1), abs(c2 - c1))
            if steps == 0:
                continue
            dr, dc = (r2 - r1) // steps, (c2 - c1) // steps
            for k in range(steps + 1):
                r, c = r1 + k * dr, c1 + k * dc
                if grid[r][c] == 9:
                    out[r][c] = 3
    return out
