def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    out = [row[:] for row in grid]

    # Fill straight gaps between markers that lie in the same row or column.
    for r in range(h):
        cols = [c for rr, c in marks if rr == r]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if out[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r, cc in marks if cc == c]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if out[r][c] == bg:
                    out[r][c] = 3
    return out
